from itertools import groupby


def squash(s: str) -> str:
    out: list[str] = []
    for c, group in groupby(s):
        k = sum(1 for _ in group)
        escaped = f"\\{c}" if ("0" <= c <= "9" or c == "\\") else c
        if k >= 3:
            out.append(f"{k}{escaped}")
        else:
            out.append(escaped * k)
    return "".join(out)
